import numpy as np,json,hashlib,time
R=Path(__file__).resolve().parents[1];P=R.parent.parent;ROOT=Path('/data/netg/ACSG');start=time.perf_counter();c=json.loads((R/'evaluate.json').read_text());d=c['dimension'];raw=np.memmap(c['base'],dtype='<f4',mode='r').reshape(-1,d+1);base=raw[:,1:]
