 q=np.fromfile(inp/'queries.f32',dtype='<f4').reshape(-1,d);g=np.fromfile(inp/'gt.i32',dtype='<i4').reshape(-1,100);a=np.fromfile(out/'k1/GT10-soft-t1_L1000/ids.i32',dtype='<i4');b=np.fromfile(out/'k1/ApproxTarget10_L1000/ids.i32',dtype='<i4');ha=a==g[:,0];hb=b==g[:,0];rows=np.where(ha!=hb)[0];data=[]
